#!/usr/bin/env python3
"""Generate exact 8-bit products for the native 32-level artwork fade."""
import argparse
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent


def compile_steps():
    rows = [" {" + ",".join(str(h * v * 31 // 65025) for v in range(256)) + "},\n"
            for h in range(256)]
    return ("// SPDX-License-Identifier: GPL-2.0-only\n"
            "// Generated by design/compile-artwork-fade.py.\n"
            "// Exact floor(horizontal * vertical * 31 / 65025), with no rounding change.\n"
            "#ifndef MP_ARTWORK_FADE_H\n#define MP_ARTWORK_FADE_H\n"
            "static const unsigned char mp_art_fade_steps[256][256]={\n"
            + "".join(rows) + "};\n#endif\n")


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--output", type=Path, default=ROOT / "native/artwork-fade.h")
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    generated = compile_steps()
    if args.check:
        if args.output.read_text() != generated:
            parser.error("Generated artwork fade is out of date")
    else:
        args.output.write_text(generated)
